const err = $input.first().json;
const workflowName = err.execution?.workflowData?.name || 'Unknown Workflow';
const errorMessage = err.execution?.lastNodeExecuted || 'No node info';
const errorMsg = err.execution?.error?.message || 'Unknown error';
const errorTime = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

const msg = `*BL Gym Automation Error Alert*\n\nWorkflow: ${workflowName}\nNode: ${errorMessage}\nError: ${errorMsg}\nTime: ${errorTime}\n\nPlease check n8n dashboard.`;

return [{ json: { alert: msg, workflow: workflowName } }];
